void MirrorModifier_mirror_object_set(PointerRNA *ptr, PointerRNA value, ReportList *reports)
{
    MirrorModifierData *data = (MirrorModifierData *)(ptr->data);
    ID *id = ptr->owner_id;
    if (id == value.data) {
      return;
    }
    if (value.data && ptr->owner_id && value.owner_id && !BKE_id_can_use_id(*ptr->owner_id, *value.owner_id)) {
      return;
    }
    if (value.data) {
        id_lib_extern((ID *)value.data);
    }
    *(void **)&data->mirror_ob = value.data;
}

