void MeshSequenceCacheModifier_cache_file_set(PointerRNA *ptr, PointerRNA value, ReportList *reports)
{
    MeshSeqCacheModifierData *data = (MeshSeqCacheModifierData *)(ptr->data);
    ID *id = ptr->owner_id;
    if (id == value.data) {
      return;
    }
    if (value.data && ptr->owner_id && value.owner_id && !BKE_id_can_use_id(*ptr->owner_id, *value.owner_id)) {
      return;
    }

    if (data->cache_file) {
        id_us_min((ID *)data->cache_file);
    }
    if (value.data) {
        id_us_plus((ID *)value.data);
    }
    *(void **)&data->cache_file = value.data;
}

