void NodesModifierBake_directory_set(PointerRNA *ptr, const char *value)
{
    NodesModifierBake *data = (NodesModifierBake *)(ptr->data);
    if (data->directory != nullptr) { MEM_delete(data->directory); }
    const size_t length = strlen(value);
    if (length > 0) {
        data->directory = MEM_new_array_uninitialized<char>(length + 1, __func__);
        memcpy(data->directory, value, length + 1);
    } else { data->directory = nullptr; }
}

