bool GreasePencilDashModifierData_segments_lookup_int(PointerRNA *ptr, int index, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;

    GreasePencilDashModifierData_segments_begin(&iter, ptr);

    if (iter.valid) {
        ArrayIterator *internal = &iter.internal.array;
        if (index < 0 || index >= internal->length) {
#ifdef __GNUC__
            printf("Array iterator out of range: %s (index %d)\n", __func__, index);
#else
            printf("Array iterator out of range: (index %d)\n", index);
#endif
        }
        else if (internal->skip) {
            while (index-- > 0 && iter.valid) {
                rna_iterator_array_next(&iter);
            }
            found = (index == -1 && iter.valid);
        }
        else {
            internal->ptr += internal->itemsize * index;
            found = 1;
        }
        if (found) { *r_ptr = GreasePencilDashModifierData_segments_get(&iter); }
    }

    GreasePencilDashModifierData_segments_end(&iter);

    return found;
}

int GreasePencilDashModifierSegment_name_length(PointerRNA *);
void GreasePencilDashModifierSegment_name_get(PointerRNA *, char *);

bool GreasePencilDashModifierData_segments_lookup_string(PointerRNA *ptr, const char *key, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;
    char namebuf[1024];
    char *name;

    GreasePencilDashModifierData_segments_begin(&iter, ptr);

    while (iter.valid) {
        if (iter.ptr.data) {
            int namelen = GreasePencilDashModifierSegment_name_length(&iter.ptr);
            if (namelen < 1024) {
                GreasePencilDashModifierSegment_name_get(&iter.ptr, namebuf);
                if (strcmp(namebuf, key) == 0) {
                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
            }
            else {
                name = MEM_new_array_uninitialized<char>(size_t(namelen) + 1,
                                               "name string");
                GreasePencilDashModifierSegment_name_get(&iter.ptr, name);
                if (strcmp(name, key) == 0) {
                    MEM_delete(name);

                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
                else {
                    MEM_delete(name);
                }
            }
        }
        GreasePencilDashModifierData_segments_next(&iter);
    }
    GreasePencilDashModifierData_segments_end(&iter);

    return found;
}

