void GreasePencilArrayModifier_offset_object_set(PointerRNA *ptr, PointerRNA value, ReportList *reports)
{
    GreasePencilArrayModifierData *data = (GreasePencilArrayModifierData *)(ptr->data);
    ID *id = ptr->owner_id;
    if (id == value.data) {
      return;
    }
    if (value.data && ptr->owner_id && value.owner_id && !BKE_id_can_use_id(*ptr->owner_id, *value.owner_id)) {
      return;
    }
    if (value.data) {
        id_lib_extern((ID *)value.data);
    }
    *(void **)&data->object = value.data;
}

